'use strict'
// A stand-in for mineflayer: every bot spawns at once and hears its own chat back.
const { EventEmitter } = require('node:events')
exports.createBot = (opts) => {
  const bot = new EventEmitter()
  bot.username = opts.username
  bot.chat = (text) => setImmediate(() => bot.emit('messagestr', `<${opts.username}> ${text}`, 'chat'))
  bot.quit = () => {}
  setImmediate(() => bot.emit('spawn'))
  return bot
}
